declare s clob;n number;
 procedure same(p_name varchar2,p_type varchar2,p_hash varchar2,p_code varchar2)is begin
  dbms_lob.createtemporary(s,true);
  for r in(select TEXT from USER_SOURCE where NAME=p_name and TYPE=p_type order by LINE)loop dbms_lob.append(s,replace(r.TEXT,chr(13),''));end loop;
  if dbms_lob.getlength(s)=0 or rawtohex(sys.dbms_crypto.hash(rtrim(s,chr(10)),sys.dbms_crypto.hash_sh256))<>p_hash then raise_application_error(-20999,p_code||':'||p_name||':'||p_type);end if;
  dbms_lob.freetemporary(s);
 end;
begin
 same('RRL_TRADE_COMPOSITION_API','PACKAGE','9615420232AEEC99E9C3B8F7326E44D34ED732D40462DE849691D7EBE2817CF5','AFTER_SOURCE_MISMATCH');
 same('RRL_TRADE_COMPOSITION_API','PACKAGE BODY','03BEB4335D0C0F98F50F65B9F5BC2480262F142E54D1778C9B733902FBF0FC18','AFTER_SOURCE_MISMATCH');
 same('RRL_ACCESS_API','PACKAGE','99900B1DBCF6FE74889F8E07A773224F0A25BD2B4EE5F61E57637E10BC50EFDF','DEPENDENCY_CHANGED');
 same('RRL_ACCESS_API','PACKAGE BODY','425772EC82A57ECA90E987322CB5151B713F8B5EB4233C64A39EDCD02A038F1C','DEPENDENCY_CHANGED');
 same('RRL_TRADE_STOCK_GUARD','PACKAGE','555A92C50609C9198308AE1E4129AECCB34E891ADC14170F016B739596B447AA','DEPENDENCY_CHANGED');
 same('RRL_TRADE_STOCK_GUARD','PACKAGE BODY','7D6E1781DB7F46AC66105865B83D583C2FF35A9A905C1D8B91C97421CF0A68EE','DEPENDENCY_CHANGED');
 same('RRL_TRACEABILITY_API','PACKAGE','899413CFFD946EC0B64111374E91E4DF2AA83EAD886F7853B6AC8FADA03A9E3B','DEPENDENCY_CHANGED');
 same('RRL_TRACEABILITY_API','PACKAGE BODY','4131765217B3C15BE5273A2539E238E5CA16C367311667D9FBBE1A8FDAE68196','DEPENDENCY_CHANGED');
 same('RRL_STOCK_PLAN_HELPER','PACKAGE','D23535D9AB6E1B735147CA77C4D31AD1727DC1F53B8C0CB89FD53515AE5444CE','DEPENDENCY_CHANGED');
 select count(*)into n from USER_OBJECTS where OBJECT_NAME in('RRL_TRADE_ORDER_COMPOSITION','RRL_TRADE_COMPOSITION_ACK','RRL_TRADE_ORDER_COMP_CUR_UK','RRL_TRADE_COMP_ACK_APPEND','RRL_TRADE_ORDER_COMP_FROZEN','RRL_TRADE_COMPOSITION_API');if n<>7 then raise_application_error(-20999,'COMPOSITION_OBJECT_MISSING');end if;
 select count(*)into n from USER_OBJECTS where STATUS='INVALID';if n<>0 then raise_application_error(-20999,'INVALID_OBJECTS');end if;
 select count(*)into n from USER_ERRORS where NAME in('RRL_TRADE_COMPOSITION_API','RRL_TRADE_COMP_ACK_APPEND','RRL_TRADE_ORDER_COMP_FROZEN');if n<>0 then raise_application_error(-20999,'COMPILE_ERRORS');end if;
end;
